import asyncio, sys, json
from playwright.async_api import async_playwright
import os
OUT=os.environ.get('CIN_OUT','/tmp/svgcinema-shots/'); os.makedirs(OUT, exist_ok=True)
# The refreshed UI: light/dark toggle, collapsible inspector sections, keyframe toggle states,
# the artboard label, the timecode total and the playhead's time flag.
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(color_scheme='light'); pg=await ctx.new_page()
        await pg.set_viewport_size({'width':1440,'height':900}); pg.set_default_timeout(5000)
        errs=[]; pg.on('pageerror',lambda e: errs.append(str(e)))
        url=(sys.argv[1] if len(sys.argv)>1 else 'http://localhost:5199/')
        await pg.goto(url, wait_until='domcontentloaded'); await pg.wait_for_timeout(2500)
        await pg.evaluate("async()=>{ window.st=await import('/src/core/state.ts'); window.hi=await import('/src/core/history.ts'); }")
        ev=lambda js: pg.evaluate(js); R={}; F=[]
        def check(n,c,i=None):
            R[n]=('ok' if c else 'FAIL')+('' if i is None else f' {i}')
            if not c: F.append(n)
        await ev("localStorage.removeItem('svgcinema:theme'); localStorage.removeItem('svgcinema:inspClosed')")
        await pg.reload(wait_until='domcontentloaded'); await pg.wait_for_timeout(2000)
        await pg.evaluate("async()=>{ window.st=await import('/src/core/state.ts'); window.hi=await import('/src/core/history.ts'); }")

        # theme toggle
        bg=lambda: ev("getComputedStyle(document.body).backgroundColor")
        light=await bg()
        check('follows the system theme until a choice is made', not await ev("document.documentElement.dataset.theme") and await ev("document.getElementById('bTheme').getAttribute('aria-label')")=='Switch to dark theme')
        check('the theme button sits in the top bar, right of Keyboard shortcuts', await ev("document.getElementById('bKeys').nextElementSibling.id")=='bTheme' and not await ev("!!document.querySelector('#tools #bTheme')"))
        # rulers are painted in script: they must repaint on the switch, not on the next redraw
        await ev("(async()=>{const v=await import('/src/core/view.ts');v.VIEW.rulers=true;const g=await import('/src/render/guides.ts');g.drawRulers()})()"); await pg.wait_for_timeout(100)
        px=lambda: ev("(()=>{const c=document.getElementById('rulerX');return [...c.getContext('2d').getImageData(2,2,1,1).data].slice(0,3).join(',')})()")
        r0=await px()
        clear=await ev("hintBtn.getBoundingClientRect().left >= rulerY.getBoundingClientRect().right")
        check('with rulers on, the ? sits clear of the left ruler', clear)
        await pg.click('#bTheme'); dark=await bg(); r1=await px()
        check('rulers repaint as soon as the theme switches', r0!=r1, (r0,r1))
        lf=await ev("[...document.querySelectorAll('.brand .logo .lg-a, .brand .logo .lg-b')].filter((e,i,a)=>i==0||e.classList[0]!==a[0].classList[0]).slice(0,2).map(e=>getComputedStyle(e).fill)")
        check('SVGcinema: page title, and the white logo in the dark theme', await ev("document.title")=='SVGcinema' and await ev("document.querySelector('.brand .logo').getAttribute('aria-label')")=='SVGcinema' and lf==['rgb(114, 138, 252)','rgb(255, 255, 255)'], lf)
        await ev("(async()=>{const v=await import('/src/core/view.ts');v.VIEW.rulers=false;const g=await import('/src/render/guides.ts');g.drawRulers()})()")
        check('the rail button switches to dark and remembers it', await ev("document.documentElement.dataset.theme")=='dark' and await ev("localStorage.getItem('svgcinema:theme')")=='dark' and dark!=light, (light,dark))
        check('the button now offers light', await ev("document.getElementById('bTheme').getAttribute('aria-label')")=='Switch to light theme')
        await pg.reload(wait_until='domcontentloaded'); await pg.wait_for_timeout(1500)
        check('dark is kept after a reload', await ev("document.documentElement.dataset.theme")=='dark' and await bg()==dark)
        await pg.screenshot(path=OUT+'ui-refresh-dark.png')
        await pg.click('#bTheme')
        check('and back to light', await ev("document.documentElement.dataset.theme")=='light' and await bg()==light)
        await pg.evaluate("async()=>{ window.st=await import('/src/core/state.ts'); window.hi=await import('/src/core/history.ts'); }")

        # artboard label, timecode total
        lab=await ev("[abName.textContent, abSize.textContent]")
        check('artboard label shows the project name and size', lab==[await ev("st.doc.name"), f"{await ev('st.doc.w')} × {await ev('st.doc.h')}"], lab)
        await pg.fill('#pname','Morning'); lab2=await ev("abName.textContent")
        check('label follows the project name while typing', lab2=='Morning', lab2)
        await pg.press('#pname','Escape')
        check('timecode shows the total length (the length field)', await ev("tcTot.textContent.trim()+' '+tDur.value")=='/ 0:03.00', await ev("tcTot.textContent.trim()+' '+tDur.value"))

        # playhead flag
        await ev("hi.setTime(1.5)")
        check('playhead flag shows the time', await ev("playhead.dataset.t")=='1.50s' and not await ev("playhead.classList.contains('at-start')"))
        await ev("hi.setTime(0)")
        check('at 0s the flag hangs right of the line', await ev("playhead.classList.contains('at-start')"))
        fz=await ev("(()=>{const n=document.querySelector('.tl-prop .tl-name');const f=n.querySelector('.tl-fz').getBoundingClientRect(),t=n.querySelector('.tl-pname').getBoundingClientRect();return [n.firstElementChild.classList.contains('tl-fz'), f.right<=t.left]})()")
        check('timeline: the freeze toggle is left of the property name', fz==[True,True], fz)

        # inspector header + keyframe states
        sid=await ev("st.doc.layers.find(l=>l.name==='Sun').id"); await ev(f"hi.select('{sid}')")
        check('layer name and type sit in the inspector header', await ev("document.querySelector('.insp-head #ln').value")=='Sun' and await ev("document.querySelector('.insp-head .chip').textContent")=='ellipse')
        check('legend in the Transforms heading', await ev("!!document.querySelector('#insp .sec h3 .kleg')"))
        kb=lambda k: ev(f"(()=>{{const b=document.querySelector('#insp [data-kb={k}]');return [b.classList.contains('has'),b.classList.contains('on'),getComputedStyle(b.closest('.row').querySelector('.rl')).color]}})()")
        off=await kb('fo')
        await pg.click('#insp [data-kb=fo]'); on=await kb('fo')
        check('◆ on fill opacity: off, then a keyframe at the playhead', off[0]==False and on[0]==True and on[1]==True, (off,on))
        check('an animated property label turns amber', on[2]!=off[2], (off[2],on[2]))
        await ev("hi.setTime(1)"); await pg.wait_for_timeout(50); mid=await kb('fo')
        check('away from the keyframe the toggle shows "animated"', mid[0]==True and mid[1]==False, mid)
        check('fill opacity has its own row and toggle, apart from the colour', await ev("!!document.querySelector('#insp [data-kb=fill]') && !!document.querySelector('#insp [data-kb=so]')"))
        check('boolean operations are still in the inspector', await ev("document.querySelectorAll('#insp [data-bool]').length")==4)
        check('number fields use the UI font with tabular digits (open zero)', await ev("(()=>{const c=getComputedStyle(document.getElementById('i-pos_0'));return c.fontFamily.includes('Instrument Sans') && c.fontVariantNumeric.includes('tabular-nums')})()"))
        check('the eyedropper icon is the new one, wherever it appears', await ev("[...document.querySelectorAll('#insp [data-act=pick] svg')].every(s=>s.querySelectorAll('path').length==4)"))
        hz=await ev("st.doc.layers.find(l=>l.name==='Horizon').id"); await ev(f"hi.select('{hz}')")
        check('Draw is gone; Trim path stays (the sample draws on with Trim End)', not await ev("!!document.querySelector('#insp [data-kb=draw]')") and await ev("!!document.querySelector('#insp [data-kb=te]') && document.querySelector('#insp [data-kb=te]').classList.contains('has')") and not await ev(f"'draw' in st.layerById('{hz}').b || 'draw' in st.layerById('{hz}').t"))
        await ev(f"hi.select('{sid}')")
        # line ends, line join and Align (closed shapes): drawn as the stroke with the path knocked out (Align's
        # inside / outside icons are just the band, smaller or larger: the owner's icons)
        check('line ends and joins: stroke shapes with the path knocked out', await ev("document.querySelectorAll('#insp .btns.lj').length")>=2 and await ev("[...document.querySelectorAll('#insp .btns.lj .btn:not([data-tx=al])')].every(b=>b.querySelector('.knock'))") and await ev("(()=>{const c=document.querySelector('#insp [data-tx=al][data-v=center]'); return !c || !!c.querySelector('.knock')})()"))
        check('a note says what the booleans need', await ev("(document.querySelector('.align-bar .ab-note')||{}).textContent")=='Booleans: select 2+ shapes')
        cf=await ev("(()=>{const c=document.getElementById('c-fill').closest('.cf');return [c.firstElementChild.className, [...c.firstElementChild.children].map(e=>e.id), [...c.children].slice(1).map(e=>e.dataset.act||'')]})()")
        check('colour field: swatch and value in one box, eyedropper beside it', cf[0]=='cbox' and cf[1]==['c-fill','t-fill'] and cf[2] in (['pick'],[]), cf)
        units=await ev("['i-scl_0_100','i-skw_0'].map(id=>{const e=document.getElementById(id).parentElement.querySelector('em');return e&&getComputedStyle(e).display!=='none'?e.textContent:''})")
        check('units show in the fields (%, °)', units==['%','°'], units)
        check('layer count in the Layers footer', await ev("lCount.textContent")=='1 of '+str(await ev("st.doc.layers.length"))+' selected', await ev("lCount.textContent"))
        check('hint: dot-separated, keys as chips', await ev("hint.querySelectorAll('i').length>=2 && hint.querySelector('kbd').textContent=='Ctrl'"))
        check('tips are hidden behind a ? button', not await pg.is_visible('#hint') and await pg.is_visible('#hintBtn'))
        await pg.hover('#hintBtn'); await pg.wait_for_timeout(100)
        check('hovering ? shows the tips', await pg.is_visible('#hint'))
        await pg.mouse.move(700,300)
        ab=await ev("(()=>{const a=getComputedStyle(lAnim),e=getComputedStyle(bExport),i=lAnimIc.getBoundingClientRect(),t=lAnim.getBoundingClientRect();return [a.backgroundColor==e.backgroundColor && a.color==e.color, getComputedStyle(lAnim,'::after').content, Math.abs((i.top+i.bottom)/2-(t.top+t.bottom)/2)<1.5]})()")
        check('Animate: Export colours, no chevron, icon centred', ab[0] and ab[1] in ('none','normal') and ab[2], ab)
        await ev("hi.select(null)"); await ev(f"hi.select('{sid}')")
        rp=await ev("(()=>{const r=document.getElementById('op-range');return [r.value, r.style.getPropertyValue('--p')]})()")
        check('sliders fill up to the thumb', rp[1]==rp[0]+'%' or (rp[0]=='100' and rp[1]=='100%'), rp)

        # collapsible sections
        heads=await ev("[...document.querySelectorAll('#insp .sec h3')].map(h=>h.childNodes[0].textContent.trim())")
        check('section titles stay the heading text', 'Transforms' in heads and 'Fill & stroke' in heads, heads)
        check('every section heading has a collapse toggle', await ev("[...document.querySelectorAll('#insp .sec > h3')].every(h=>h.querySelector('.sec-tg'))"))
        await pg.click('#insp .sec h3:has-text("Transforms")')
        closed=lambda: ev("[...document.querySelectorAll('#insp .sec.closed h3')].map(h=>h.childNodes[0].textContent.trim())")
        c1=await closed()
        check('clicking a heading collapses the section', c1==['Transforms'] and not await ev("document.querySelector('#insp [data-kb=pos]').checkVisibility()"), c1)
        await pg.click('#insp [data-act=swap]'); c2=await closed()
        check('a button in a heading does not toggle it', c2==['Transforms'], c2)
        await ev("hi.undo()")
        pid=await ev("st.doc.layers.find(l=>l.name==='Blob').id"); await ev(f"hi.select('{pid}')")
        check('collapsed sections stay collapsed for other layers', await closed()==['Transforms'])
        await pg.reload(wait_until='domcontentloaded'); await pg.wait_for_timeout(1500)
        await pg.evaluate("async()=>{ window.st=await import('/src/core/state.ts'); window.hi=await import('/src/core/history.ts'); }")
        await ev(f"hi.select('{pid}')")
        check('and after a reload', await closed()==['Transforms'])
        await pg.focus('#insp .sec.closed .sec-tg'); await pg.keyboard.press('Enter')
        check('the toggle opens it from the keyboard', await closed()==[] and await ev("document.querySelector('#insp .sec-tg').getAttribute('aria-expanded')")=='true')
        await pg.screenshot(path=OUT+'ui-refresh-light.png')
        R['errors']=errs; print(json.dumps(R,indent=1,ensure_ascii=False)); print('FAILS',F+(['errors'] if errs else []))
        await b.close()
asyncio.run(main())
